{
  "items": [
    {
      "name": "MvPolynomial.coeff",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "definition",
      "type": "{R : Type u} → {σ : Type u_1} → [inst : CommSemiring R] → (σ →₀ ℕ) → MvPolynomial σ R → R"
    },
    {
      "name": "Polynomial.mahlerMeasure_le_sum_norm_coeff",
      "module_name": "Mathlib.Analysis.Polynomial.MahlerMeasure",
      "kind": "theorem",
      "type": "∀ (p : Polynomial ℂ), p.mahlerMeasure ≤ p.sum fun x a => ‖a‖"
    },
    {
      "name": "MvPolynomial.eval_eq",
      "module_name": "Mathlib.Algebra.MvPolynomial.Eval",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (X : σ → R) (f : MvPolynomial σ R),\n  (MvPolynomial.eval X) f = ∑ d ∈ f.support, MvPolynomial.coeff d f * ∏ i ∈ d.support, X i ^ d i"
    },
    {
      "name": "MvPolynomial.coeffs",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "definition",
      "type": "{R : Type u} → {σ : Type u_1} → [inst : CommSemiring R] → MvPolynomial σ R → Finset R"
    },
    {
      "name": "Poly",
      "module_name": "Mathlib.NumberTheory.Dioph",
      "kind": "definition",
      "type": "Type u → Type (max 0 u)"
    },
    {
      "name": "MvPolynomial.totalDegree_monomial",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (s : σ →₀ ℕ) {c : R},\n  c ≠ 0 → ((MvPolynomial.monomial s) c).totalDegree = s.sum fun x e => e"
    },
    {
      "name": "MvPolynomial.support_sum_monomial_coeff",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (p : MvPolynomial σ R),\n  ∑ v ∈ p.support, (MvPolynomial.monomial v) (MvPolynomial.coeff v p) = p"
    }
  ]
}
